catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
   if (isLoading || newValue == '') {
      return;
   }

   if (newValue) {
      var transfertype = g_form.getValue('transfer_type');
    //   g_form.addInfoMessage('hospital newValue (sys_id): ' + newValue + ' | transfer_type: ' + transfertype);

      if (transfertype == 2 || transfertype == 3) {
         g_form.getReference('hospital', function(hosRec) {
            if (hosRec && hosRec.name) {
               g_form.setValue('pickup_address', hosRec.name);
            //    g_form.addInfoMessage('pickup_address set from hospital.name: ' + hosRec.name);
            } else {
               g_form.setValue('pickup_address', '');
               g_form.addInfoMessage('hospital name not found on referenced record');
            }
         });
      }
   }
}
